import { client } from "../../config/config.js";

// create table public.body_avaliacoes (
//   id bigint generated by default as identity not null,
//   created_at timestamp with time zone not null default now(),
//   owner_id uuid null default auth.uid (),
//   schema_id bigint null,
//   avaliador text null,
//   metodo text null,
//   value jsonb null,
//   data_registro timestamp with time zone null,
//   constraint body_avaliacoes_pkey primary key (id),
//   constraint body_avaliacoes_schema_id_fkey foreign KEY (schema_id) references body_schema (id)
// ) TABLESPACE pg_default;

export const BodyAvaliacoesService = {
  // LISTAR (READ)
  async getAll() {
    const { data, error } = await client
      .from("body_avaliacoes")
      .select("*")
      .order("data_registro", { ascending: false });

    if (error) {
      console.error("Erro ao buscar avaliações corporais:", error);
      throw error;
    }
    return data;
  },
  async getById(id) {
    const { data, error } = await client
      .from("body_avaliacoes")
      .select("*")
      .eq("id", id)
      .single();
    if (error) {
      console.error("Erro ao buscar avaliação corporal por ID:", error);
      throw error;
    }
    return data;
  },
  async getLastRegistered() {
    const { data, error } = await client
      .from("body_avaliacoes")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(1)
      .single();
    if (error) {
      console.error(
        "Erro ao buscar última avaliação corporal registrada:",
        error,
      );
      throw error;
    }
    return data;
  },
  async create(avaliacaoData) {
    // avaliacaoData deve ser { schema_id: ID, avaliador: "...", metodo: "...", value: {...}, data_registro: "..." }
    const { data, error } = await client
      .from("body_avaliacoes")
      .insert([avaliacaoData])
      .select();
    if (error) {
      console.error("Erro ao criar avaliação corporal:", error);
      throw error;
    }
    return data;
  },
  async delete(id) {
    const { data, error } = await client
      .from("body_avaliacoes")
      .delete()
      .eq("id", id);
    if (error) {
      console.error("Erro ao deletar avaliação corporal:", error);
      throw error;
    }
    return data;
  },
  async update(id, avaliacaoData) {
    const { data, error } = await client
      .from("body_avaliacoes")
      .update(avaliacaoData)
      .eq("id", id);
    if (error) {
      console.error("Erro ao atualizar avaliação corporal:", error);
      throw error;
    }
    return data;
  },
};
